INSERT INTO daily_quote(content, translation, note, category, language, source_type) VALUES
    ('No worries, I’ll swing by this arvo.', '沒問題，我今天下午會順道過去。', 'No worries 是澳洲萬用回應（沒關係／不客氣）；arvo 是 afternoon（下午）。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Let’s grab brekkie before heading out.', '我們出門前先去吃個早餐吧。', 'brekkie 是早餐；咖啡館常見的 all-day brekkie 整天都點得到。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('I reckon we should stop by the servo for petrol.', '我覺得我們應該順路去加油站加油。', 'reckon 常用來代替 think；servo 是加油站（service station）。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Sorry, I’ve been flat out this week.', '抱歉，我這週忙翻了。', 'flat out 形容非常忙，很適合用來解釋沒回訊息或推掉邀約。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Yeah, nah, I’ll give it a miss tonight.', '嗯…不了，今晚我先不去。', 'Yeah, nah 是委婉的「不要」；give it a miss 是這次跳過。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('How ya going?', '你好嗎？最近怎樣？', '澳洲最常見的打招呼，回 Good, thanks! 就好，不用真的報告近況。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Can I get a flat white, thanks?', '可以給我一杯 flat white 嗎？謝謝。', 'flat white 是澳洲咖啡館的招牌；點餐用 Can I get… 加 thanks 很自然。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Mate, you’re a legend!', '兄弟，你太讚了！', '有人幫你大忙時說 You’re a legend；mate 不分男女都可以用。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('It’s my shout this time.', '這次我請客。', 'shout 在這裡是「請客」；一群人輪流請喝一輪叫 shout a round。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Is it alright if I knock off a bit early today?', '我今天可以早一點下班嗎？', 'knock off 是下班、收工；用 Is it alright if… 問主管比較禮貌。', 'WORKING_HOLIDAY', 'en-AU', 'ORIGINAL'),
    ('What time do we start tomorrow?', '我們明天幾點開工？', '跟主管或同事確認上班時間的實用句，start 就是開工。', 'WORKING_HOLIDAY', 'en-AU', 'ORIGINAL'),
    ('I’m rostered on for Saturday.', '我星期六有排班。', 'rostered on 是被排進班表；rostered off 是排休。', 'WORKING_HOLIDAY', 'en-AU', 'ORIGINAL'),
    ('Would you be keen to swap shifts on Friday?', '星期五你願意跟我換班嗎？', 'keen 是有意願、很想；swap shifts 是換班，記得先問主管可不可以。', 'WORKING_HOLIDAY', 'en-AU', 'ORIGINAL'),
    ('We’re having smoko in five.', '再五分鐘休息一下。', 'smoko 原本指抽菸休息，現在泛指工作中的短暫休息。', 'WORKING_HOLIDAY', 'en-AU', 'ORIGINAL'),
    ('Just chuck it in the bin, mate.', '丟垃圾桶就好。', 'chuck 是丟、扔，日常口語非常常用。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('She’ll be right.', '會沒事的啦。', '澳洲人樂觀的口頭禪，意思是「別擔心，會順利的」。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Too easy!', '小事一樁！', '答應別人請求時說，跟 No worries 一樣常聽到。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Good on ya!', '做得好！', '稱讚或鼓勵別人；ya 是 you 的口語說法。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Fair dinkum? That’s unreal!', '真的假的？太誇張了吧！', 'fair dinkum 表示「真的嗎／貨真價實」；unreal 在口語裡是「超讚、難以置信」。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('I’m heading to Woolies after work.', '下班後我要去 Woolworths。', 'Woolies 是 Woolworths 超市的暱稱。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Grab some snags for the barbie.', '買些香腸來烤肉。', 'snags 是香腸，barbie 是 barbecue（烤肉）。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Don’t forget your thongs and togs.', '別忘了帶夾腳拖和泳衣。', '在澳洲 thongs 是夾腳拖，togs 是泳衣（NSW 也常說 swimmers）。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('It’s a bit nippy this morning.', '今天早上有點冷。', 'nippy 是微冷、冷颼颼。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('It’s gonna be a scorcher, so slip, slop, slap.', '今天會超熱，記得做好防曬。', 'scorcher 是大熱天；Slip, Slop, Slap 是澳洲防曬口號：穿上衣、擦防曬、戴帽子。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Could you give me a lift to the station?', '可以載我去車站嗎？', 'give someone a lift 是順路載人一程。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('I need to top up my Opal card.', '我要儲值 Opal 卡。', 'Opal 是雪梨與 NSW 的交通卡；top up 是儲值。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Are you right there?', '需要幫忙嗎？', '店員常這樣問，意思接近 Can I help you?', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Cheers for that!', '謝啦！', 'cheers 除了乾杯，也是很常用的「謝謝」。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('I’ll be there in a tick.', '我馬上到。', 'in a tick 是一下子、馬上。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Let’s catch up for a cuppa sometime.', '找天一起喝杯茶聊聊吧。', 'cuppa 是一杯茶或咖啡；catch up 是見面敘舊。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Sorry, I didn’t catch that. Could you say it again?', '抱歉我沒聽清楚，可以再說一次嗎？', '聽不懂時最實用的一句，對方通常很樂意再說一次。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('What’s the go with the new roster?', '新的班表是怎麼回事？', 'What’s the go 是「情況怎樣」的口語說法。', 'WORKING_HOLIDAY', 'en-AU', 'ORIGINAL'),
    ('I’m stuffed after that double shift.', '上完那個雙班我累癱了。', 'stuffed 是累壞了，也可以指吃很飽。', 'WORKING_HOLIDAY', 'en-AU', 'ORIGINAL'),
    ('That’s heaps good!', '那超棒的！', 'heaps 是很多、非常，澳洲人非常常用。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('I’ve got heaps of washing to do.', '我有一大堆衣服要洗。', 'heaps of 等於 a lot of。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Is it BYO?', '可以自己帶酒嗎？', 'BYO 是 bring your own，常見於餐廳或派對邀請。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('We’re going bush this weekend.', '這週末我們要去郊外。', 'go bush 是到鄉下、野外走走。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Watch out for roos on the road at dusk.', '傍晚開車要小心路上的袋鼠。', 'roo 是 kangaroo；黃昏和清晨是袋鼠最常出沒的時候。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('My ute’s parked out the back.', '我的小貨車停在後面。', 'ute 是 utility vehicle，澳洲很常見的皮卡車。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Fill in your timesheet before you head off.', '走之前把工時表填好。', 'timesheet 是工時紀錄，跟薪水直接相關，別忘了填。', 'WORKING_HOLIDAY', 'en-AU', 'ORIGINAL'),
    ('When’s payday this week?', '這週什麼時候發薪？', 'payday 是發薪日；很多工作是每週或每兩週發一次。', 'WORKING_HOLIDAY', 'en-AU', 'ORIGINAL'),
    ('Could you email me my payslip, please?', '可以把薪資單寄到我的信箱嗎？', 'payslip 是薪資單，收到後記得留存並核對工時與時薪。', 'WORKING_HOLIDAY', 'en-AU', 'ORIGINAL'),
    ('I’m feeling a bit crook today.', '我今天有點不舒服。', 'crook 是生病、不舒服。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('I need to call in sick today.', '我今天要請病假。', 'call in sick 是打電話請病假；可以順便問主管需不需要證明。', 'WORKING_HOLIDAY', 'en-AU', 'ORIGINAL'),
    ('Shall we split the bill?', '我們要不要分開付？', 'split the bill 是平分帳單。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Do you reckon it’ll rain later?', '你覺得等一下會下雨嗎？', 'reckon 用來問別人的看法非常自然。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Sounds like a plan!', '就這麼辦！', '同意別人提議時的輕鬆說法。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Take it easy, mate.', '放輕鬆，慢慢來。', '也常用在道別，有「保重」的意思。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Catch ya later!', '待會見！', '澳洲人道別常說 Catch ya later 或 See ya。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Have a good one!', '祝你今天順利！', '道別時的萬用祝福，回 You too! 就好。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Hooroo!', '掰啦！', '比較老派又親切的澳洲式再見。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('I’m just having a squiz, thanks.', '我只是看看，謝謝。', 'squiz 是看一眼；逛街被店員招呼時很好用。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('That job sounds a bit dodgy.', '那份工作聽起來有點可疑。', 'dodgy 是不可靠、怪怪的；時薪低得不合理的工作要特別小心。', 'WORKING_HOLIDAY', 'en-AU', 'ORIGINAL'),
    ('Mind if I jump in?', '我可以加入嗎？', 'jump in 是插話或加入一起做。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('It’s chockers at the shops today.', '今天商店人超多。', 'chockers 是擠滿、塞爆（來自 chock-a-block）。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Could I grab a receipt, please?', '可以給我收據嗎？', '買工作用品、制服時記得留收據，報稅時可能用得到。', 'WORKING_HOLIDAY', 'en-AU', 'ORIGINAL'),
    ('Let’s have a yarn after work.', '下班後聊一下吧。', 'yarn 在澳洲口語裡是聊天、閒聊。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('I’m knackered, I’m gonna hit the sack.', '我累死了，要去睡了。', 'knackered 是累壞了；hit the sack 是去睡覺。', 'LIFE', 'en-AU', 'ORIGINAL'),
    ('Can you show me how to do this one more time?', '可以再示範一次怎麼做嗎？', '剛上工時多問一次沒關係，做對比做快更重要。', 'WORKING_HOLIDAY', 'en-AU', 'ORIGINAL'),
    ('Where do I put my PPE at the end of the shift?', '下班時防護裝備要放哪裡？', 'PPE 是個人防護裝備，例如手套、護目鏡、安全鞋。', 'WORKING_HOLIDAY', 'en-AU', 'ORIGINAL')
